struct htp_conn_t {
    char *client_addr;
    int client_port;
    char *server_addr;
    int server_port;
    htp_list_t *transactions;
    htp_list_t *messages;
    uint8_t flags;
    htp_time_t open_timestamp;
    htp_time_t close_timestamp;
    int64_t in_data_counter;
    int64_t out_data_counter;
};

struct htp_file_t {
    enum htp_file_source_t source;
    bstr *filename;
    int64_t len;
    char *tmpname;
    int fd;
};

struct htp_file_data_t {
    htp_file_t *file;
    const unsigned char *data;
    size_t len;
};

struct htp_log_t {
    htp_connp_t *connp;
    htp_tx_t *tx;
    const char *msg;
    enum htp_log_level_t level;
    int code;
    const char *file;
    unsigned int line;
};

struct htp_header_t {
    bstr *name;
    bstr *value;
    uint64_t flags;
};

struct htp_param_t {
    bstr *name;
    bstr *value;
    enum htp_data_source_t source;
    enum htp_parser_id_t parser_id;
    void *parser_data;
};

struct htp_tx_t {
    htp_connp_t *connp;
